from datetime import date
from decimal import Decimal

from app.domain import (
    ExchangeRate,
    Member,
    SplitKind,
    Trip,
)
from app.logic import rate_for_currency


def make_trip(*rates: ExchangeRate) -> Trip:
    return Trip(
        trip_id="trip-1",
        name="Test trip",
        base_currency="USD",
        members=(Member("member-1", "Ada"),),
        rates=rates,
        actions=(),
        closed=False,
    )


def test_rate_for_currency_returns_the_unique_matching_rate() -> None:
    trip = make_trip(
        ExchangeRate("USD", Decimal("1")),
        ExchangeRate("EUR", Decimal("1.25")),
    )

    assert rate_for_currency(trip, "EUR") == Decimal("1.25")


def test_rate_for_currency_returns_none_when_currency_has_no_match() -> None:
    trip = make_trip(ExchangeRate("USD", Decimal("1")))

    assert rate_for_currency(trip, "GBP") is None


def test_rate_for_currency_matches_currency_case_sensitively() -> None:
    trip = make_trip(ExchangeRate("EUR", Decimal("1.25")))

    assert rate_for_currency(trip, "eur") is None


def test_rate_for_currency_returns_none_when_multiple_rates_match() -> None:
    trip = make_trip(
        ExchangeRate("USD", Decimal("1")),
        ExchangeRate("USD", Decimal("1.01")),
    )

    assert rate_for_currency(trip, "USD") is None


def test_rate_for_currency_does_not_validate_rate_positivity() -> None:
    trip = make_trip(ExchangeRate("ZERO", Decimal("0")))

    assert rate_for_currency(trip, "ZERO") == Decimal("0")

