import pytest
from datetime import date
from decimal import Decimal

from app.domain import *
from app.abilities import *
from app.fakes import *
from app.logic import validate_payment


def make_trip():
    return Trip(
        trip_id="trip-1",
        name="Weekend",
        base_currency="USD",
        members=(
            Member(member_id="a", name="Alice"),
            Member(member_id="b", name="Bob"),
        ),
        rates=(),
        actions=(),
        closed=False,
    )


def make_payment(**changes):
    values = {
        "payment_id": "payment-1",
        "from_member_id": "a",
        "to_member_id": "b",
        "amount_cents": 125,
        "note": "settle",
        "occurred_on": date(2026, 1, 1),
    }
    values.update(changes)
    return Payment(**values)


def test_validate_payment_accepts_valid_payment():
    assert validate_payment(make_payment(), make_trip()) is None


@pytest.mark.parametrize(
    "changes",
    (
        {"payment_id": ""},
        {"note": ""},
    ),
)
def test_validate_payment_rejects_empty_identity_fields(changes):
    assert validate_payment(make_payment(**changes), make_trip()) == "invalid payment identity"


@pytest.mark.parametrize(
    "changes",
    (
        {"from_member_id": "missing"},
        {"to_member_id": "missing"},
        {"from_member_id": "missing", "to_member_id": "also-missing"},
    ),
)
def test_validate_payment_rejects_unknown_members(changes):
    assert validate_payment(make_payment(**changes), make_trip()) == "unknown payment member"


def test_validate_payment_checks_identity_before_member_and_amount_errors():
    payment = make_payment(
        payment_id="",
        from_member_id="missing",
        to_member_id="missing",
        amount_cents=0,
    )

    assert validate_payment(payment, make_trip()) == "invalid payment identity"


def test_validate_payment_rejects_same_known_member_as_sender_and_recipient():
    payment = make_payment(from_member_id="a", to_member_id="a", amount_cents=1)

    assert validate_payment(payment, make_trip()) == "payment members must differ"


@pytest.mark.parametrize("amount_cents", (0, -1, True, False, 1.0, Decimal("1")))
def test_validate_payment_rejects_non_positive_or_non_integer_amounts(amount_cents):
    payment = make_payment(amount_cents=amount_cents)

    assert validate_payment(payment, make_trip()) == "invalid payment amount"

