import dataclasses
from datetime import date
from decimal import Decimal

import pytest

from app.domain import *
from app.abilities import *
from app.fakes import *
from app.logic import validate_trip_configuration
from stateless import run, supply


def valid_trip(**changes):
    trip = Trip(
        trip_id="trip-1",
        name="Weekend away",
        base_currency="USD",
        members=(Member("a", "Alice"),),
        rates=(ExchangeRate("USD", Decimal("1")),),
        actions=(),
        closed=False,
    )
    return dataclasses.replace(trip, **changes)


def expense_action(expense_id: str) -> ExpenseAction:
    return ExpenseAction(
        Expense(
            expense_id=expense_id,
            payer_id="a",
            amount=Decimal("10"),
            currency="USD",
            split_kind=SplitKind.EQUAL,
            entries=(SplitEntry("a", Decimal("10")),),
            description="Dinner",
            occurred_on=date(2025, 1, 1),
        )
    )


def payment_action(payment_id: str) -> PaymentAction:
    return PaymentAction(
        Payment(
            payment_id=payment_id,
            from_member_id="a",
            to_member_id="b",
            amount_cents=100,
            note="Settled",
            occurred_on=date(2025, 1, 1),
        )
    )


def test_valid_configuration_and_decimal_equal_to_one_are_accepted():
    assert validate_trip_configuration(valid_trip()) is None
    assert (
        validate_trip_configuration(
            valid_trip(rates=(ExchangeRate("USD", Decimal("1.00")),))
        )
        is None
    )


@pytest.mark.parametrize("field", ("trip_id", "name", "base_currency"))
def test_trip_identity_fields_must_be_nonempty(field):
    assert (
        validate_trip_configuration(valid_trip(**{field: ""}))
        == "invalid trip identity"
    )

    assert (
        validate_trip_configuration(
            valid_trip(trip_id="", members=(), rates=(ExchangeRate("EUR", Decimal("1")),))
        )
        == "invalid trip identity"
    )


def test_members_are_required_and_member_ids_must_be_unique_and_nonempty():
    assert (
        validate_trip_configuration(
            valid_trip(members=(), rates=(ExchangeRate("EUR", Decimal("1")),))
        )
        == "no members"
    )

    assert (
        validate_trip_configuration(valid_trip(members=(Member("", "Alice"),)))
        == "duplicate or empty member id"
    )

    assert (
        validate_trip_configuration(
            valid_trip(members=(Member("a", "Alice"), Member("a", "Another Alice")))
        )
        == "duplicate or empty member id"
    )

    assert (
        validate_trip_configuration(
            valid_trip(
                members=(Member("a", "Alice"), Member("a", "Another Alice")),
                rates=(
                    ExchangeRate("USD", Decimal("1")),
                    ExchangeRate("EUR", Decimal("2")),
                    ExchangeRate("EUR", Decimal("3")),
                ),
            )
        )
        == "duplicate or empty member id"
    )


@pytest.mark.parametrize(
    "rates, expected",
    (
        (
            (
                ExchangeRate("USD", Decimal("1")),
                ExchangeRate("EUR", Decimal("2")),
                ExchangeRate("EUR", Decimal("3")),
            ),
            "duplicate rate currency",
        ),
        (
            (
                ExchangeRate("USD", Decimal("1")),
                ExchangeRate("EUR", Decimal("0")),
            ),
            "invalid exchange rate",
        ),
        (
            (
                ExchangeRate("USD", Decimal("1")),
                ExchangeRate("EUR", Decimal("-1")),
            ),
            "invalid exchange rate",
        ),
        (
            (
                ExchangeRate("USD", Decimal("1")),
                ExchangeRate("EUR", Decimal("Infinity")),
            ),
            "invalid exchange rate",
        ),
        (
            (
                ExchangeRate("USD", Decimal("1")),
                ExchangeRate("EUR", Decimal("NaN")),
            ),
            "invalid exchange rate",
        ),
    ),
)
def test_rate_currencies_and_values_are_validated_before_base_rate_rules(rates, expected):
    assert validate_trip_configuration(valid_trip(rates=rates)) == expected

    assert (
        validate_trip_configuration(
            valid_trip(
                rates=(
                    ExchangeRate("USD", Decimal("1")),
                    ExchangeRate("EUR", Decimal("2")),
                    ExchangeRate("EUR", Decimal("0")),
                )
            )
        )
        == "duplicate rate currency"
    )


def test_base_currency_rate_must_exist_and_equal_one():
    assert (
        validate_trip_configuration(
            valid_trip(rates=(ExchangeRate("EUR", Decimal("1.1")),))
        )
        == "missing base rate"
    )

    assert (
        validate_trip_configuration(
            valid_trip(rates=(ExchangeRate("USD", Decimal("0.99")),))
        )
        == "base rate must be 1"
    )

    assert (
        validate_trip_configuration(
            valid_trip(
                rates=(ExchangeRate("USD", Decimal("2")),),
                actions=(expense_action(""),),
            )
        )
        == "base rate must be 1"
    )


def test_action_ids_must_be_nonempty_and_unique_across_expenses_and_payments():
    assert (
        validate_trip_configuration(valid_trip(actions=(expense_action(""),)))
        == "duplicate or empty action id"
    )

    assert (
        validate_trip_configuration(valid_trip(actions=(payment_action(""),)))
        == "duplicate or empty action id"
    )

    assert (
        validate_trip_configuration(
            valid_trip(actions=(expense_action("same"), expense_action("same")))
        )
        == "duplicate or empty action id"
    )

    assert (
        validate_trip_configuration(
            valid_trip(actions=(expense_action("same"), payment_action("same")))
        )
        == "duplicate or empty action id"
    )

