import dataclasses
from datetime import date
from decimal import Decimal

from app.domain import *
from app.abilities import *
from app.fakes import *
from app.logic import compute_balances
from stateless import run, supply


def _trip(actions=(), member_ids=("a", "b")):
    return Trip(
        trip_id="trip-1",
        name="Test trip",
        base_currency="USD",
        members=tuple(Member(member_id, member_id.upper()) for member_id in member_ids),
        rates=(ExchangeRate("USD", Decimal("1")),),
        actions=tuple(actions),
        closed=False,
    )


def _equal_expense(expense_id, payer_id, amount, member_ids=("a", "b")):
    return ExpenseAction(
        Expense(
            expense_id=expense_id,
            payer_id=payer_id,
            amount=Decimal(amount),
            currency="USD",
            split_kind=SplitKind.EQUAL,
            entries=tuple(
                SplitEntry(member_id, Decimal("0")) for member_id in member_ids
            ),
            description=expense_id,
            occurred_on=date(2026, 1, 1),
        )
    )


def _payment(payment_id, from_member_id, to_member_id, cents):
    return PaymentAction(
        Payment(
            payment_id=payment_id,
            from_member_id=from_member_id,
            to_member_id=to_member_id,
            amount_cents=cents,
            note=payment_id,
            occurred_on=date(2026, 1, 1),
        )
    )


def test_compute_balances_includes_all_members_for_empty_history():
    trip = _trip(member_ids=("a", "b", "c"))

    assert compute_balances(trip) == {"a": 0, "b": 0, "c": 0}


def test_compute_balances_reports_equal_expense_in_base_cents():
    trip = _trip(actions=(_equal_expense("expense-1", "a", "1.00"),))

    assert compute_balances(trip) == {"a": 50, "b": -50}


def test_compute_balances_applies_payment_after_expense():
    expense = _equal_expense("expense-1", "a", "1.00")
    payment = _payment("payment-1", "b", "a", 50)  # fixed by hand: spec example had the direction backwards
    trip = _trip(actions=(expense, payment))

    assert compute_balances(trip) == {"a": 0, "b": 0}


def test_compute_balances_keeps_unaffected_trip_members_at_zero():
    trip = _trip(
        actions=(_equal_expense("expense-1", "a", "1.00", ("a", "b")),),
        member_ids=("a", "b", "c"),
    )

    assert compute_balances(trip) == {"a": 50, "b": -50, "c": 0}


def test_compute_balances_merges_all_expense_and_payment_deltas():
    trip = _trip(
        actions=(
            _equal_expense("expense-1", "a", "1.00"),
            _equal_expense("expense-2", "b", "2.00"),
            _payment("payment-1", "a", "b", 25),
        )
    )

    assert compute_balances(trip) == {"a": -25, "b": 25}


def test_compute_balances_merges_multiple_payments():
    trip = _trip(
        actions=(
            _payment("payment-1", "a", "b", 30),
            _payment("payment-2", "b", "c", 10),
        ),
        member_ids=("a", "b", "c"),
    )

    assert compute_balances(trip) == {"a": 30, "b": -20, "c": -10}

