import pytest

from app.domain import *
from app.logic import settle_up


@pytest.mark.parametrize(
    "balances, expected",
    [
        (
            {"a": -50, "b": 50},
            (Transfer("a", "b", 50),),
        ),
        (
            {"a": -30, "b": -20, "c": 50},
            (
                Transfer("a", "c", 30),
                Transfer("b", "c", 20),
            ),
        ),
        (
            {"a": -5, "b": 5, "c": -7, "d": 7},
            (
                Transfer("a", "b", 5),
                Transfer("c", "d", 7),
            ),
        ),
    ],
)
def test_settle_up_spec_examples(balances, expected):
    assert settle_up(balances) == expected


def test_settle_up_chooses_lexicographically_smallest_maximum_partition():
    balances = {"a": -5, "b": -5, "c": 5, "d": 5}

    assert settle_up(balances) == (
        Transfer("a", "c", 5),
        Transfer("b", "d", 5),
    )


def test_settle_up_pairs_smallest_debtor_and_creditor_until_group_is_clear():
    balances = {"a": -5, "b": -3, "c": 4, "d": 4}

    assert settle_up(balances) == (
        Transfer("a", "c", 4),
        Transfer("a", "d", 1),
        Transfer("b", "d", 3),
    )


def test_settle_up_sorts_transfers_after_processing_groups():
    balances = {"a": 2, "z": -2, "b": 3, "c": -3}

    assert settle_up(balances) == (
        Transfer("c", "b", 3),
        Transfer("z", "a", 2),
    )


def test_settle_up_ignores_zero_balances_and_does_not_mutate_input():
    balances = {"ignored": 0, "a": -10, "b": 10}
    original = dict(balances)

    assert settle_up(balances) == (Transfer("a", "b", 10),)
    assert balances == original


def test_settle_up_zero_balances_do_not_count_toward_member_limit():
    balances = {
        **{f"n{i}": -1 for i in range(6)},
        **{f"p{i}": 1 for i in range(6)},
        **{f"zero{i}": 0 for i in range(20)},
    }

    assert settle_up(balances) == tuple(
        Transfer(f"n{i}", f"p{i}", 1) for i in range(6)
    )


@pytest.mark.parametrize(
    "balances, message",
    [
        ({"a": -1, "b": 2}, "unbalanced"),
        (
            {
                **{f"creditor{i}": 1 for i in range(12)},
                "debtor": -12,
            },
            "too many members",
        ),
    ],
)
def test_settle_up_rejects_unbalanced_or_too_large_settlements(balances, message):
    with pytest.raises(ValueError) as error:
        settle_up(balances)

    assert error.value.args == (message,)
